<script setup lang="ts">
import { computed,nextTick,onActivated,onBeforeUnmount,onDeactivated,onMounted,ref,watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { CalendarRange,ExternalLink,Loader2,RefreshCw,Trash2,X } from 'lucide-vue-next'
import { supabase } from '@/lib/supabase'
import { useAuthStore } from '@/stores/auth'
import { isDialogBackdropDoubleClick } from '@/lib/utils'
import { calendarAuthorizationUrl,calendarProvider,calendarProviderName,createConnectedCalendars,type CalendarProvider,type ConnectedEvent } from '../lib/connectedCalendars'
import CalendarProviderIcon from './CalendarProviderIcon.vue'
const props=defineProps<{start:string;end:string}>(),emit=defineEmits<{'update:events':[events:ConnectedEvent[]]}>(),{t,locale}=useI18n(),auth=useAuthStore()
const owner=auth.user?.id,active=ref(true),connecting=ref<CalendarProvider|null>(null),dialog=ref<HTMLDialogElement>(),opened=ref(false),event=ref<ConnectedEvent|null>(null)
const current=()=>active.value&&Boolean(owner)&&auth.user?.id===owner
const state=createConnectedCalendars(async body=>{
 const result=await supabase.functions.invoke('outlook-calendar',{body,timeout:90000})
 if(result.error){let code='UNAVAILABLE';try{const response=result.error.context as Response;code=response.status===404?'SETUP_REQUIRED':(await response.clone().json()).error||code}catch{}throw Error(code)}
 return result.data
},current)
const {connections,events,providers,loading,busy,error,eventError,loadingEvents,selected}=state
const providerOptions:CalendarProvider[]=['outlook','google']
const allIds=computed(()=>connections.value.flatMap(connection=>connection.calendars).map(calendar=>calendar.id))
const message=(code:string)=>t('connectedCalendars.errors.'+(['SETUP_REQUIRED','REAUTH_REQUIRED','RATE_LIMITED','TOO_MANY_EVENTS','BUSY','AUTH_REQUIRED'].includes(code)?code:'UNAVAILABLE'))
let previous:HTMLElement|null=null,overflow='',rootOverflow='',timer:ReturnType<typeof setTimeout>|undefined,lastRefresh=0
watch(events,value=>{if(current())emit('update:events',value)},{immediate:true})
watch([()=>props.start,()=>props.end,()=>selected.value.join(','),state.configured],()=>{if(timer)clearTimeout(timer);timer=undefined;if(!current())return;state.invalidate();timer=setTimeout(()=>{timer=undefined;if(current())void state.loadEvents(props.start,props.end)},120)})
watch(()=>auth.user?.id,()=>{if(auth.user?.id!==owner){close(true);state.reset();emit('update:events',[])}})
function open(){event.value=null;show();void state.load()}
function openEvent(value:ConnectedEvent){event.value=value;show()}
function show(){if(opened.value)return;previous=document.activeElement as HTMLElement;overflow=document.body.style.overflow;rootOverflow=document.documentElement.style.overflow;document.documentElement.style.overflow='hidden';document.body.style.overflow='hidden';opened.value=true;void nextTick(()=>dialog.value?.showModal())}
function close(force=false){if((busy.value||connecting.value)&&!force)return;if(opened.value){dialog.value?.close();opened.value=false;document.body.style.overflow=overflow;document.documentElement.style.overflow=rootOverflow;previous?.focus({preventScroll:true})}}
async function connect(provider:CalendarProvider){if(connecting.value||busy.value||!providers.value[provider])return;connecting.value=provider;error.value='';try{const result=await supabase.functions.invoke('outlook-calendar',{body:{action:'connect',provider,return_url:window.location.origin+'/'}});if(result.error){let code='UNAVAILABLE';try{code=(await (result.error.context as Response).clone().json()).error}catch{}throw Error(code)}const url=calendarAuthorizationUrl(result.data.url,provider);if(current())window.location.assign(url)}catch(failure){if(current())error.value=(failure as Error).message}finally{connecting.value=null}}
function select(id:string,checked:boolean){const ids=checked?[...selected.value,id]:selected.value.filter(value=>value!==id);if(ids.length>10){error.value='TOO_MANY_EVENTS';return}void state.mutate('select',{ids})}
async function refresh(id:string){await state.mutate('sync',{id});lastRefresh=Date.now()}
function focused(){if(current()&&Date.now()-lastRefresh>60000){lastRefresh=Date.now();void state.loadEvents(props.start,props.end,true)}}
function describe(value:ConnectedEvent){if(value.allDay){const last=new Date(value.end+'T12:00:00Z');last.setUTCDate(last.getUTCDate()-1);const format=new Intl.DateTimeFormat(locale.value==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',timeZone:'UTC'});return format.format(new Date(value.start+'T12:00:00Z'))+(value.start===last.toISOString().slice(0,10)?'':' – '+format.format(last))+' · '+t('connectedCalendars.allDay')}return new Intl.DateTimeFormat(locale.value==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value.start))+' – '+new Intl.DateTimeFormat(locale.value==='tr'?'tr-TR':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value.end))}
onMounted(()=>{void state.load();window.addEventListener('focus',focused)})
onActivated(()=>{if(!active.value){active.value=true;void state.load().then(()=>state.loadEvents(props.start,props.end,true))}})
onDeactivated(()=>{active.value=false;if(timer)clearTimeout(timer);timer=undefined;close(true);state.suspend()})
onBeforeUnmount(()=>{active.value=false;if(timer)clearTimeout(timer);close(true);state.reset();window.removeEventListener('focus',focused)})
defineExpose({openEvent})
</script>
<template>
 <button type="button" class="calendar-icon calendar-bordered" :class="{'is-connected':selected.length>0,'has-issue':Boolean(eventError)}" :aria-label="t('connectedCalendars.title')" :title="eventError?message(eventError):t('connectedCalendars.title')" @click="open"><Loader2 v-if="loadingEvents" :size="15" class="animate-spin motion-reduce:animate-none" /><CalendarRange v-else :size="15" /></button>
 <span v-if="eventError" role="status" class="sr-only">{{ message(eventError) }}</span>
 <Teleport to="body"><dialog v-if="opened" ref="dialog" class="connected-dialog" :aria-label="t('connectedCalendars.title')" @cancel.prevent="close()" @dblclick="value=>{if(isDialogBackdropDoubleClick(value))close()}">
  <header><span class="inline-flex items-center gap-2"><CalendarRange :size="16" />{{ t(event?'connectedCalendars.event':'connectedCalendars.title') }}</span><button type="button" :disabled="busy||Boolean(connecting)" :aria-label="t('common.close')" @click="close()"><X :size="18" /></button></header>
  <div class="connected-body">
   <template v-if="event"><span class="connected-source"><CalendarProviderIcon :provider="calendarProvider(event)" :size="17" /><i :style="{backgroundColor:event.color}" />{{ event.calendar_name }} · {{ calendarProviderName(calendarProvider(event)) }}</span><h3>{{ event.title||t(event.private?'connectedCalendars.privateEvent':'connectedCalendars.untitled') }}</h3><p class="connected-copy">{{ describe(event) }}</p><p v-if="event.location" class="connected-copy">{{ event.location }}</p><p class="connected-copy">{{ t('connectedCalendars.readOnly') }}</p><a v-if="event.url" :href="event.url" target="_blank" rel="noopener noreferrer" class="connected-button"><ExternalLink :size="14" />{{ t('connectedCalendars.openProvider',{provider:calendarProviderName(calendarProvider(event))}) }}</a></template>
   <template v-else>
    <p class="connected-copy">{{ t('connectedCalendars.personal') }}</p>
    <p v-if="loading" role="status" class="connected-copy">{{ t('app.loading') }}</p>
    <div v-if="connections.length" class="connected-selection"><span>{{ t('connectedCalendars.selected',{count:selected.length}) }}</span><button type="button" :disabled="busy||allIds.length>10" @click="state.mutate('select',{ids:allIds})">{{ t('connectedCalendars.all') }}</button><button type="button" :disabled="busy||!selected.length" @click="state.mutate('select',{ids:[]})">{{ t('connectedCalendars.clear') }}</button></div>
    <article v-for="connection in connections" :key="connection.id" class="connected-account"><div class="connected-account-heading"><CalendarProviderIcon :provider="connection.provider" :size="23" /><div><strong>{{ calendarProviderName(connection.provider) }}</strong><span :title="connection.label">{{ connection.label }}</span></div><button type="button" :disabled="busy" :aria-label="t('connectedCalendars.refresh')" @click="refresh(connection.id)"><RefreshCw :size="14" /></button><button type="button" :disabled="busy" class="is-delete" :aria-label="t('connectedCalendars.disconnect')" @click="state.mutate('disconnect',{id:connection.id})"><Trash2 :size="14" /></button></div><button v-if="connection.status==='reauth'" type="button" class="connected-reconnect" :disabled="Boolean(connecting)||busy||!providers[connection.provider]" @click="connect(connection.provider)">{{ t('connectedCalendars.reconnect') }}</button><label v-for="calendar in connection.calendars" :key="calendar.id" class="connected-calendar"><input type="checkbox" :checked="calendar.selected" :disabled="busy" @change="value=>{const input=value.target as HTMLInputElement;const checked=input.checked;input.checked=calendar.selected;select(calendar.id,checked)}" /><i :style="{backgroundColor:calendar.color}" /><span>{{ calendar.name }}</span></label></article>
    <p v-if="error" role="alert" class="connected-error">{{ message(error) }} <button type="button" :disabled="loading||busy" @click="state.load().then(()=>state.loadEvents(props.start,props.end,true))">{{ t('tasks.retry') }}</button></p><p v-if="eventError" role="status" class="connected-copy">{{ message(eventError) }}</p>
    <div class="connected-providers"><button v-for="provider in providerOptions" :key="provider" type="button" class="connected-button connected-provider" :disabled="!providers[provider]||Boolean(connecting)||busy||loading" :data-provider="provider" @click="connect(provider)"><Loader2 v-if="connecting===provider" :size="21" class="animate-spin" /><CalendarProviderIcon v-else :provider="provider" :size="24" /><span><strong>{{ calendarProviderName(provider) }}</strong><small>{{ t(providers[provider]?'connectedCalendars.connectAccount':'connectedCalendars.setupPending') }}</small></span></button></div><p class="connected-copy">{{ t('connectedCalendars.readOnly') }}</p>
   </template>
  </div>
 </dialog></Teleport>
</template>
<style scoped>
.calendar-icon{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:32px;height:32px;border:1px solid hsl(var(--border)/.6);border-radius:9px;color:hsl(var(--muted-foreground))}.calendar-icon.is-connected{color:hsl(var(--primary))}.calendar-icon.has-issue{color:hsl(var(--destructive)/.8)}.calendar-icon:hover{background:hsl(var(--muted)/.5)}.connected-button{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:36px;padding:9px 12px;border:1px solid hsl(var(--border));border-radius:10px;font-size:12px;color:hsl(var(--foreground))}

.connected-dialog{width:min(480px,calc(100vw - 24px));max-height:calc(100dvh - 48px);padding:0;margin:auto;border:1px solid hsl(var(--border)/.7);border-radius:18px;background:hsl(var(--card));color:hsl(var(--foreground));box-shadow:0 24px 80px #0002;overflow:hidden}.connected-dialog::backdrop{background:hsl(var(--background)/.75);backdrop-filter:blur(6px)}.connected-dialog[open]{display:flex;flex-direction:column}.connected-dialog header{display:flex;align-items:center;justify-content:space-between;flex-shrink:0;padding:17px 20px;border-bottom:1px solid hsl(var(--border)/.6);font-size:13px;font-weight:500}.connected-dialog button:not(.connected-button){border-radius:8px;padding:6px;color:hsl(var(--muted-foreground))}.connected-dialog button:hover{background:hsl(var(--muted)/.5);color:hsl(var(--foreground))}.connected-dialog button:disabled{opacity:.4}.connected-body{overflow-y:auto;padding:20px;display:flex;flex-direction:column;gap:16px}.connected-copy{font-size:11px;line-height:1.7;color:hsl(var(--muted-foreground))}.connected-account{border:1px solid hsl(var(--border)/.65);border-radius:13px;padding:12px}.connected-account-heading{display:flex;align-items:center;gap:5px;margin-bottom:9px}.connected-account-heading>div{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}.connected-account-heading strong{font-size:12px;font-weight:500}.connected-account-heading span{font-size:10px;color:hsl(var(--muted-foreground));overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.connected-account-heading .is-delete:hover{color:hsl(var(--destructive));background:hsl(var(--destructive)/.06)}.connected-calendar{display:flex;align-items:center;gap:9px;padding:8px 3px;font-size:12px;cursor:pointer}.connected-calendar input{accent-color:hsl(var(--primary));width:14px;height:14px}.connected-calendar i,.connected-source i{width:8px;height:8px;flex-shrink:0;border-radius:3px}.connected-selection{display:flex;align-items:center;gap:8px;font-size:10px;color:hsl(var(--muted-foreground))}.connected-selection>span{margin-right:auto}.connected-providers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.connected-provider{justify-content:flex-start;gap:10px;padding:12px;text-align:left}.connected-provider>span{display:flex;flex-direction:column;gap:3px;min-width:0}.connected-provider strong{font-size:11px;font-weight:500}.connected-provider small{font-size:10px;color:hsl(var(--muted-foreground))}.connected-provider:disabled{opacity:.55!important}.connected-account-heading>svg{margin-right:6px}.connected-source{display:flex;align-items:center;gap:7px;font-size:11px;color:hsl(var(--muted-foreground))}.connected-body h3{font-size:17px;line-height:1.5;font-weight:500;overflow-wrap:anywhere}.connected-error{font-size:11px;color:hsl(var(--destructive))}.connected-status{flex-basis:100%;font-size:10px;color:hsl(var(--muted-foreground))}.connected-dialog button:focus-visible,.connected-dialog a:focus-visible{outline:2px solid hsl(var(--primary)/.35);outline-offset:2px}.connected-reconnect{font-size:11px;color:hsl(var(--primary))!important}
</style>
